200			for _, f := range req[k] {
201				vers = append(vers, f.ver)
202			}
203			sort.Slice(vers, func(a, b int) bool { return vers[a].seq < vers[b].seq })
204			buckets := make([][]nodeVer, n+1)
205			for _, ver := range vers {
206				j := segmentFor(ver.seq, watermarks)
207				buckets[j] = append(buckets[j], ver)
208				if j < n {
209					// Versions are ascending, so the last one placed at or before
210					// watermark j is its terminal there.
211					terminalAt[j][k] = ver
212				} else {
213					tailKeySet[k] = struct{}{}
214				}
215			}
216			for j := range buckets {
217				if len(buckets[j]) > 0 {
218					segments[j] = append(segments[j], keyHistory{key: k, versions: buckets[j]})
219				}
220			}
221		}
222		// terminalAt[j] must see the newest frame <= watermark j across ALL
223		// earlier segments, not only frames placed into segment j: propagate
224		// terminals forward across watermarks.
225		for j := 1; j < n; j++ {
226			for k, v := range terminalAt[j-1] {
227				if _, ok := terminalAt[j][k]; !ok {
228					terminalAt[j][k] = v
229				}
230			}
231		}
232		for j := range segments {
233			sort.Slice(segments[j], func(a, b int) bool { return segments[j][a].key < segments[j][b].key })
234		}
235	
236		layers := make([]rebuiltLayer, n)
237		for j := 0; j < n; j++ {
238			var entries []checkpointEntry
239			// Deterministic key order over this watermark's full terminal state.
240			ks := make([]string, 0, len(terminalAt[j]))
241			for k := range terminalAt[j] {
242				ks = append(ks, k)
243			}
244			sort.Strings(ks)
245			if j == 0 {
246				// Full base: complete terminal state at the oldest window layer.
247				entries = make([]checkpointEntry, 0, len(ks))
248				for _, k := range ks {
249					entries = append(entries, entryFromVer(k, terminalAt[j][k]))
250				}
251			} else {
252				// Delta: only keys whose terminal version changed since the
253				// previous window layer (including appearance and deletion).
254				entries = make([]checkpointEntry, 0)
255				for _, k := range ks {
256					prev, had := terminalAt[j-1][k]
257					cur := terminalAt[j][k]
258					if had && prev.seq == cur.seq {
259						continue
260					}
261					entries = append(entries, entryFromVer(k, cur))
262				}
263			}
264			layers[j] = rebuiltLayer{entries: entries, seq: watermarks[j], snaps: snaps[j]}
265		}
266	
267		tailKeys := make([]string, 0, len(tailKeySet))
268		for k := range tailKeySet {
269			tailKeys = append(tailKeys, k)
270		}
271		sort.Strings(tailKeys)
272		return &segmentedWAL{segments: segments, layers: layers, tailKeys: tailKeys}
273	}
274	
275	func entryFromVer(key string, ver nodeVer) checkpointEntry {
276		e := checkpointEntry{key: key, seq: ver.seq, present: ver.present}
277		if ver.present {
278			e.value = cloneBytes(ver.value)
279		}
280		return e
281	}
282	
283	// encodeHistoryFrames buffers one key history's frames oldest-to-newest.
284	func encodeHistoryFrames(l *walWriter, h keyHistory) error {
285		for _, ver := range h.versions {
286			if ver.present {
287				if err := l.encodeFrameSeq(opPutSeq, h.key, ver.seq, ver.value); err != nil {
288					return err
289				}
290			} else {
291				if err := l.encodeFrameSeq(opDeleteSeq, h.key, ver.seq, nil); err != nil {
292					return err
293				}
294			}
295		}
296		return nil
297	}
298	
299	// buildSegmentedCompactArtifacts writes the complete replacement WAL (one
300	// contiguous segment per surviving layer followed by the post-window tail and
301	// the snapshot-count meta) and stages the re-anchored chain under
302	// stagedChainDir. Nothing the store currently uses is touched: on any error
303	// all staged files are removed and the old WAL and chain stay authoritative.
304	func buildSegmentedCompactArtifacts(dir string, seg *segmentedWAL, snapshotCount uint64) error {
305		if err := removeStaleCompact(dir); err != nil {
306			return err
307		}
308		if err := os.RemoveAll(filepath.Join(dir, stagedChainDir)); err != nil {
309			return err
310		}
311	
312		path := dir + string(os.PathSeparator)
313		tmp, err := os.OpenFile(path+compactTmpName, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
314		if err != nil {
315			return err
316		}
317		fail := func(err error) error {
318			tmp.Close()
319			os.Remove(path + compactTmpName)
320			os.RemoveAll(path + stagedChainDir)
321			return err
322		}
323		l := &walWriter{f: tmp, w: bufio.NewWriter(tmp)}
324	
325		// Write segments in order; the cut of layer j is the file position right
326		// after its segment, which is an exact frame boundary (the next segment's
327		// first frame starts there).
328		cuts := make([]int64, len(seg.layers))
329		for j, hists := range seg.segments {
330			for i := range hists {
331				if err := encodeHistoryFrames(l, hists[i]); err != nil {
332					return fail(err)
333				}
334			}
335			if j < len(seg.layers) {
336				if err := l.w.Flush(); err != nil {
337					return fail(err)
338				}
339				pos, perr := tmp.Seek(0, 2)
340				if perr != nil {
341					return fail(perr)
342				}
343				cuts[j] = pos
344			}
345		}
346		if snapshotCount > 0 {
347			var v [metaValueSize]byte
348			binary.LittleEndian.PutUint64(v[:], snapshotCount)
349			if err := l.encodeFrame(opMeta, "", v[:]); err != nil {
350				return fail(err)
351			}
352		}
353		if err := l.w.Flush(); err != nil {
354			return fail(err)
355		}
356		if err := tmp.Sync(); err != nil {
357			return fail(err)
358		}
359		if err := tmp.Close(); err != nil {
360			return fail(err)
361		}
362	
363		// Stage the replacement chain: layer j references cut j of the new WAL.
364		// Layers link by content hash, so each prevCRC is the CRC of the file
365		// written immediately before it and must be filled in write order.
366		stagePath := filepath.Join(dir, stagedChainDir)
367		if err := os.MkdirAll(stagePath, 0o700); err != nil {
368			return fail(errors.New("snapshot: cannot stage checkpoint chain"))
369		}
370		var prevCRC uint32
371		for j, meta := range seg.layers {
372			layer := capturedLayer{
373				index:   uint32(j),
374				prevCRC: prevCRC,
375				entries: meta.entries,
376				offset:  uint64(cuts[j]),
377				seq:     meta.seq,
378				snaps:   meta.snaps,
379			}
380			name := layerFileName(uint32(j))
381			crc, werr := writeLayerFile(dir, filepath.Join(stagedChainDir, filepath.Base(name)), layer)
382			if werr != nil {
383				return fail(werr)
384			}
385			prevCRC = crc
386		}
387		if err := syncDirectory(stagePath); err != nil {
388			return fail(err)
389		}
390		seg.cuts = cuts
391		return nil
392	}
393	
394	// activateStagedChain promotes the staged replacement chain into place after
395	// the replacement WAL has been renamed over wal.log, and forces the parent
396	// directory. Its absence means compaction simply leaves no live checkpoint.
397	func activateStagedChain(dir string) error {
398		stage := filepath.Join(dir, stagedChainDir)
399		if _, err := os.Stat(stage); err != nil {
400			if errors.Is(err, os.ErrNotExist) {
401				return nil
402			}
403			return err
404		}
405		if err := os.RemoveAll(filepath.Join(dir, checkpointDirName)); err != nil {
406			return err
407		}
408		if err := os.Rename(stage, filepath.Join(dir, checkpointDirName)); err != nil {
409			return err
410		}
411		return syncDirectory(dir)
412	}
413	
414	// removeStagedChain best-effort deletes a staged replacement chain.
415	func removeStagedChain(dir string) error {
416		err := os.RemoveAll(filepath.Join(dir, stagedChainDir))
417		if err != nil && !errors.Is(err, os.ErrNotExist) {
418			return err
419		}
420		return nil
421	}
422	
423	// replaceCheckpointChain atomically swaps the live chain for layers. It
424	// stages the new chain, durably removes the old one and promotes the staging
425	// directory; the WAL (and every layer cut it references) is left untouched,
426	// so this is used both when Checkpoint prunes the retention window and never
427	// by compaction (which stages alongside its new WAL).
428	func replaceCheckpointChain(dir string, layers []capturedLayer) error {
429		if err := os.RemoveAll(filepath.Join(dir, stagedChainDir)); err != nil {
430			return err
431		}
432		stagePath := filepath.Join(dir, stagedChainDir)
433		if err := os.MkdirAll(stagePath, 0o700); err != nil {
434			return err
435		}
436		fail := func(err error) error {
437			os.RemoveAll(stagePath)
438			return err
439		}
440		// Layers link by content hash; fill prevCRC in write order regardless of
441		// what the caller populated, so the rebuilt chain is always self-consistent.
442		var prevCRC uint32
443		for _, layer := range layers {
444			layer.prevCRC = prevCRC
445			name := filepath.Base(layerFileName(layer.index))
446			crc, werr := writeLayerFile(dir, filepath.Join(stagedChainDir, name), layer)
447			if werr != nil {
448				return fail(werr)
449			}
450			prevCRC = crc
451		}
452		if err := syncDirectory(stagePath); err != nil {
453			return fail(err)
454		}
455		if err := os.RemoveAll(filepath.Join(dir, checkpointDirName)); err != nil {
456			return fail(err)
457		}
458		if err := os.Rename(stagePath, filepath.Join(dir, checkpointDirName)); err != nil {
459			return fail(err)
460		}
461		return syncDirectory(dir)
462	}
463	
464	// sortEntries orders layer entries by key.
465	func sortEntries(entries []checkpointEntry) {
466		sort.Slice(entries, func(i, j int) bool { return entries[i].key < entries[j].key })
467	}
