// and registers it so compaction retains its versions.
func (s *Store) newCursor(v *view, start, end string) *Cursor {
	c := newCursorPinned(s, v, start, end)
	s.registerCursor(c)
	return c
}

func newCursorPinned(st *Store, v *view, start, end string) *Cursor {
	return &Cursor{
		store: st,
		v:     v,
		start: start,
		end:   end,
